/**
 * RecordedRun
 *
 * One recorded run on any branch, for run diff (US-54.6).
 *
 * ``request`` is the user turn the run answers; ``steps`` are its assistant
 * steps along that branch, in order. Everything is as recorded at execution.
 */
export const zRecordedRun = z.object({
  request: zMessage,
  steps: z.array(zMessage),
});

/**
 * UserFile
 *
 * Public representation of one file in the caller's library.
 *
 * Attributes:
 * id: File identifier.
 * filename: Unique display name inside the caller's library.
 * original_name: The sanitized name the client uploaded.
 * size: Size in bytes of the stored source.
 * mime_type: Detected MIME type.
 * kind: Classification driving conversion and model input.
 * content_status: State of the converted-content cache.
 * content_error: Reason for a failed/unsupported conversion, if any.
 * created_at: Creation time as whole Unix seconds.
 * updated_at: Last update time as whole Unix seconds.
 * thumbnail: Data-URL preview for images, else ``None``.
 * origin: Whether the user uploaded the file or an agent tool produced it.
 * projects: Projects that currently attach this file.
 * knowledge: Latest knowledge artifact for this file, if one exists.
 */
export const zUserFile = z.object({
  id: z.uuid(),
  filename: z.string(),
  original_name: z.string(),
  size: z.int().gte(0),
  mime_type: z.string(),
  kind: zFileKind,
  content_status: zFileContentStatus,
  content_error: z.string().nullable(),
  created_at: z.int(),
  updated_at: z.int(),
  thumbnail: z.string().nullable(),
  origin: zFileOrigin,
  projects: z.array(zFileProjectSummary).optional(),
  knowledge: zFileKnowledgeArtifact.nullish(),
});

/**
 * SimilarFile
 *
 * One file ranked against a query file by embedding similarity.
 *
 * Attributes:
 * file: The matching file.
 * score: Cosine similarity between the query file's centroid direction
 * and the candidate's best-matching chunk, clamped to ``[-1, 1]``.
 */
export const zSimilarFile = z.object({
  file: zUserFile,
  score: z.number().gte(-1).lte(1),
});

/**
 * SimilarFileList
 *
 * Ranked list of files similar to a query file.
 *
 * Attributes:
 * files: Candidates ordered by descending similarity score.
 */
export const zSimilarFileList = z.object({
  files: z.array(zSimilarFile),
});

/**
 * UserFileList
 *
 * A page of files plus the pagination envelope.
 *
 * Attributes:
 * files: Files on this page.
 * total: Total number of matching files across all pages.
 * page: 1-based page number that was returned.
 * page_size: Number of files requested per page.
 */
export const zUserFileList = z.object({
  files: z.array(zUserFile),
  total: z.int().gte(0).optional().default(0),
  page: z.int().gte(1).optional().default(1),
  page_size: z.int().gte(1).optional().default(50),
});

/**
 * UserSettings
 *
 * Aggregate of one user's settings as returned by ``GET /settings/user``.
 *
 * ``main_agent``/``sub_agents`` are injected by the service from the agent
 * domain; ``models`` is the list of all active models across providers.
 */
export const zUserSettings = z.object({
  theme: z.string().optional().default("atlas"),
  font_size: z.string().optional().default("16px"),
  models: z.array(zLlmDisplayInfo).optional(),
  default_model_id: z.uuid().nullish(),
  main_agent: zMainAgentConfiguration,
  sub_agents: z.record(z.string(), zSubAgentDefinition).optional(),
  show_thinking: z.boolean().optional().default(true),
  prompt_coach_enabled: z.boolean().optional().default(false),
  first_chat_tour: z.enum(["completed", "dismissed"]).nullish(),
});

